ow new Exception("Install failed");string save=Path.Combine(root,"install","saves");Directory.CreateDirectory(save);File.WriteAllText(Path.Combine(save,"character.json"),"keep");var bad=Data.Read<Feed>(Data.Write(f));bad.Version="0.2.0";bad.Sha256=new string('0',64);Reject(()=>install.Install(bad,zip));if(install.Current().Version!="0.1.0")throw new Exception("Bad checksum changed active build");foreach(string path in new[]{"../escape.exe","/absolute.exe","C:/escape.exe","dir/../../escape.exe","game.exe:stream","dir\\escape"})Reject(()=>Installer.SafePath(root,path));string attack=Path.Combine(root,"attack.zip");using(var z=ZipFile.Open(attack,ZipArchiveMode.Create))z.CreateEntry("../escape.exe");Reject(()=>install.Extract(attack,Path.Combine(root,"stage"),f));f.Version="0.2.0";custom.Install(f,zip);if(!File.Exists(custom.GamePath(f))||custom.Current().Version!=f.Version)throw new Exception("Custom folder install failed");install.Install(f,zip);if(install.Current().Version!="0.2.0"||!File.Exists(Path.Combine(root,"install","versions","0.1.0","Game.exe"))||File.ReadAllText(Path.Combine(save,"character.json"))!="keep")throw new Exception("Update did not preserve old build/save");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"launcher-checks.txt"),"PASS: GitHub repository URL normalization and same-repository release enforcement; first install, version activation, checksum rejection, path traversal rejection, malformed ZIP rejection, old-build retention, external save preservation.");}finally{Directory.Delete(root,true);}}
